def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r,c) in seen:
                continue
            q = [(r,c)]; seen.add((r,c)); cells=[]
            for x,y in q:
                cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 3 and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            if len(cells) >= 10:
                rs=[x for x,y in cells]; cs=[y for x,y in cells]
                boxes.append((min(rs),max(rs),min(cs),max(cs),len(cells)))
    targets=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1 for r0,r1,c0,c1,_ in boxes):
                targets.append((r,c))
    out=[row[:] for row in grid]
    for r,c in targets:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                nr,nc=r+dr,c+dc
                if (dr or dc) and 0 <= nr < h and 0 <= nc < w and out[nr][nc] != 2:
                    out[nr][nc]=1
    return out

